# Big 12 opponents plus the non-conference names on the 2025 card. Config-free:
# any of these appearing as a literal in markup is a hand-edit waiting to happen.
OPPONENTS = [
    "Kansas State", "Kansas", "TCU", "Texas Tech", "Oklahoma State", "Iowa State",
    "Cincinnati", "Houston", "BYU", "Utah", "Arizona", "Arizona State", "Colorado",
    "UCF", "West Virginia", "Auburn", "SMU", "Samford", "Arkansas",
]
TIER_WORDS = ["elite", "poor", "weak", "bad", "underperform", "disappointing",
              "worst", "lazy", "soft"]
EXEMPT = {"config.py", "audit.py"}


def _python_docstring_and_comment_spans(text: str) -> list[tuple[int, int, int, int]]:
    """1-indexed-line/0-indexed-col spans of every `#` comment and every module,
    class or function docstring in a Python source file. Neither is printed to
    a sheet, so neither counts as a hand-edit."""
    spans = []
    try:
        for tok in tokenize.generate_tokens(io.StringIO(text).readline):
            if tok.type == tokenize.COMMENT:
                (sr, sc), (er, ec) = tok.start, tok.end
                spans.append((sr, sc, er, ec))
    except (tokenize.TokenError, IndentationError):
        pass
    try:
        tree = ast.parse(text)
    except SyntaxError:
        tree = None
    if tree is not None:
        doc_holders = (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)
        for node in ast.walk(tree):
            if not isinstance(node, doc_holders) or not node.body:
                continue
            first = node.body[0]
            if (isinstance(first, ast.Expr) and isinstance(first.value, ast.Constant)
                    and isinstance(first.value.value, str)):
                v = first.value
                spans.append((v.lineno, v.col_offset, v.end_lineno, v.end_col_offset))
    return spans


def _blank(text: str, spans: list[tuple[int, int, int, int]]) -> str:
    lines = text.splitlines(keepends=True)
    for sr, sc, er, ec in spans:
        if sr == er:
            line = lines[sr - 1]
            lines[sr - 1] = line[:sc] + " " * (ec - sc) + line[ec:]

